package cn.gmiya.malodylink;

import android.app.Activity;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** Competition boards: category selection, medal podium and compact ranked rows. */
public final class RankingHub extends LinearLayout {
    private final Activity host;private final Engine engine;private SongCatalogue catalogue;private final BiConsumer<Boolean,Integer> remember;private final Consumer<String> searchMemory;private String query,boardId="total",notice="";
    private final Map<String,JSONArray> extra=new HashMap<>();
    private final ExecutorService io=Executors.newSingleThreadExecutor();private CommunityData.Boards boards;private RankingPanel singlePanel;private ScrollView scroll;private TextView status;private boolean closed,loading,showHiddenCreators;private int page,request,homeY;
    public RankingHub(Activity host,Engine engine,boolean single,int cid,String query,BiConsumer<Boolean,Integer> remember,Consumer<String> searchMemory){super(host);this.host=host;this.engine=engine;this.query=query;this.remember=remember;this.searchMemory=searchMemory;showHiddenCreators=host.getSharedPreferences("community",0).getBoolean("show_hidden_creators",false);catalogue=new SongCatalogue(engine.charts());setOrientation(VERTICAL);setBackground(new CharacterBackdrop(host,2));if(single)openSingle(cid);else{home();load(true);}}
    private int dp(int n){return AppUi.dp(host,n);}
    private void clear(){if(scroll!=null&&page==0)homeY=scroll.getScrollY();scroll=null;if(singlePanel!=null){singlePanel.close();singlePanel=null;}removeAllViews();setPadding(dp(16),dp(16),dp(16),0);}
    private void title(String text){addView(AppUi.text(host,text,26,AppUi.INK,true));AppUi.space(this,8);}
    private void buttons(String left,Runnable first,String right,Runnable second){LinearLayout row=new LinearLayout(host);row.addView(AppUi.button(host,left,first),new LayoutParams(0,-2,1));LayoutParams rp=new LayoutParams(0,-2,1);rp.leftMargin=dp(8);row.addView(AppUi.button(host,right,second),rp);addView(row);}
    private JSONArray rows(String id){try{if(extraId(id))return extra.getOrDefault(id,new JSONArray());return boards==null?new JSONArray():boards.rows(id.equals("creator_hot")&&showHiddenCreators&&boards.doc.getJSONObject("boards").has("creator_hot_all")?"creator_hot_all":id);}catch(Exception invalid){return new JSONArray();}}
    private void creatorToggle(LinearLayout parent){CheckBox toggle=new CheckBox(host);toggle.setText("显示默认隐藏的谱师");toggle.setTextColor(AppUi.INK);toggle.setTextSize(14);toggle.setMinHeight(dp(48));toggle.setChecked(showHiddenCreators);parent.addView(toggle);parent.addView(AppUi.text(host,"imddesigner 始终隐藏",12,AppUi.MUTED,false));AppUi.space(parent,8);toggle.setOnCheckedChangeListener((v,checked)->{showHiddenCreators=checked;host.getSharedPreferences("community",0).edit().putBoolean("show_hidden_creators",checked).apply();render();});}
    private void labelStatus(){status=AppUi.text(host,loading?"正在读取榜单…":notice.isEmpty()?(boards!=null&&boards.cached?"显示缓存 · ":"")+(playerId(boardId)?"云端榜单 · 下拉区域可滚动查看":"热度按下载次数 · 好评按平均星级"):notice,12,AppUi.MUTED,false);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);status.setPadding(0,dp(8),0,dp(12));addView(status);}
    private void home(){
        clear();page=0;remember.accept(false,0);title("排行榜");buttons("单曲榜 · 选歌",()->openSingle(0),"刷新榜单",()->load(true));labelStatus();
        LinearLayout tabs=new LinearLayout(host);String[] ids={"total","six_k","activity_month","song_hot"},labels={"总战力","6K","活跃度","更多榜单"};
        for(int i=0;i<ids.length;i++){final String id=ids[i];Button tab=AppUi.button(host,labels[i],()->selectBoard(id));boolean selected=id.equals(boardId)||(id.equals("activity_month")&&boardId.startsWith("activity_"))||(id.equals("song_hot")&&!playerId(boardId));tab.setBackgroundTintList(android.content.res.ColorStateList.valueOf(selected?AppUi.SELECTED:AppUi.CARD));tab.setTextColor(selected?AppUi.ACCENT:AppUi.MUTED);tab.setTextSize(12);tab.setPadding(0,0,0,0);tab.setSelected(selected);tabs.addView(tab,new LayoutParams(0,dp(48),1));}addView(tabs);AppUi.space(this,8);
        if(boardId.startsWith("activity_")){buttons("近30天",()->selectBoard("activity_month"),"累计",()->selectBoard("activity_total"));AppUi.space(this,8);}
        else if(!playerId(boardId)){Spinner picker=new Spinner(host);String[] options=Arrays.copyOfRange(CommunityData.TITLES,1,CommunityData.TITLES.length);picker.setAdapter(new ArrayAdapter<>(host,android.R.layout.simple_spinner_dropdown_item,options));int chosen=0;for(int i=1;i<CommunityData.IDS.length;i++)if(CommunityData.IDS[i].equals(boardId))chosen=i-1;picker.setSelection(chosen);picker.setContentDescription("歌曲与谱师榜单分类");addView(picker,new LayoutParams(-1,dp(48)));picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){String next=CommunityData.IDS[position+1];if(!boardId.equals(next))selectBoard(next);}});}
        scroll=new ScrollView(host);scroll.setFillViewport(true);LinearLayout body=AppUi.column(host,0);scroll.addView(body);addView(scroll,new LayoutParams(-1,0,1));
        final String id=boardId;JSONArray data=rows(id);AppUi.space(body,12);
        if(playerId(id)&&data.length()>0){LinearLayout podium=new LinearLayout(host);podium.setGravity(Gravity.BOTTOM);int[] order=data.length()>=3?new int[]{1,0,2}:data.length()==2?new int[]{0,1}:new int[]{0};for(int n:order){JSONObject row=data.optJSONObject(n);LinearLayout card=AppUi.column(host,10);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setBackground(surface(engine.profile.equals(row.optString("qq"))?AppUi.SELECTED:AppUi.CARD));int rank=row.optInt("rank",n+1);if(rank==1)AppUi.space(card,14);card.addView(rankMark(rank,44));card.addView(AppUi.text(host,"第"+rank+"名",12,AppUi.MUTED,true));AppUi.space(card,8);TextView name=text(row.optString("name"),13,AppUi.INK,true,2);name.setGravity(Gravity.CENTER);name.setMinLines(2);card.addView(name,new LayoutParams(-1,-2));TextView score=text(value(id,row),17,AppUi.ACCENT,true,1);score.setAutoSizeTextTypeUniformWithConfiguration(11,17,1,android.util.TypedValue.COMPLEX_UNIT_SP);score.setGravity(Gravity.CENTER);card.addView(score,new LayoutParams(-1,dp(30)));card.addView(AppUi.text(host,id.startsWith("activity_")?"次游玩":"rating",12,AppUi.MUTED,false));LayoutParams cp=new LayoutParams(0,-2,1);cp.setMargins(dp(3),0,dp(3),0);podium.addView(card,cp);}body.addView(podium);AppUi.space(body,20);}
        body.addView(AppUi.text(host,boardTitle(id),20,AppUi.INK,true));body.addView(AppUi.text(host,explanation(id),12,AppUi.MUTED,false));AppUi.space(body,12);if(id.equals("creator_hot"))creatorToggle(body);
        if(data.length()==0)body.addView(AppUi.text(host,loading?"正在读取榜单…":"暂无已发布数据，点刷新重试",14,AppUi.MUTED,false));
        for(int n=0;n<Math.min(50,data.length());n++){body.addView(compactRow(id,data.optJSONObject(n)));AppUi.space(body,6);}AppUi.space(body,12);
        if(playerId(id)){JSONObject me=null;for(int n=0;n<data.length();n++){JSONObject row=data.optJSONObject(n);if(engine.profile.equals(row.optString("qq"))){me=row;break;}}LinearLayout mine=AppUi.column(host,12);mine.setBackground(surface(AppUi.SELECTED));mine.addView(AppUi.text(host,me==null?(engine.profile.isEmpty()?"设置QQ并同步后查看我的名次":loading?"正在查找我的名次…":"我暂未进入已发布榜单"):"我的名次  #"+me.optInt("rank")+"    "+value(id,me)+(id.startsWith("activity_")?" 次":" rating"),14,AppUi.ACCENT,true));addView(mine,new LayoutParams(-1,-2));}
        final ScrollView current=scroll;current.post(()->current.scrollTo(0,homeY));
    }
    private void selectBoard(String id){boardId=id;homeY=0;if(scroll!=null)scroll.scrollTo(0,0);home();}
    private View rankMark(int rank,int size){if(rank>=1&&rank<=3){RankMedal medal=new RankMedal(host,rank);medal.setLayoutParams(new LayoutParams(dp(size),dp(size)));return medal;}TextView label=text(Integer.toString(rank),15,AppUi.MUTED,true,1);label.setGravity(Gravity.CENTER);label.setLayoutParams(new LayoutParams(dp(size),dp(size)));return label;}
    private View compactRow(String id,JSONObject row){LinearLayout card=AppUi.column(host,12);card.setOrientation(HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setBackground(surface(playerId(id)&&engine.profile.equals(row.optString("qq"))?AppUi.SELECTED:AppUi.CARD));card.addView(rankMark(row.optInt("rank"),32));View icon=art(id,row,36);LayoutParams iconp=new LayoutParams(dp(36),dp(36));iconp.setMargins(dp(6),0,dp(10),0);card.addView(icon,iconp);LinearLayout info=AppUi.column(host,0);info.addView(text(row.optString("name")+(playerId(id)&&engine.profile.equals(row.optString("qq"))?" · 我":""),14,AppUi.INK,true,2));info.addView(text(playerId(id)?id.startsWith("activity_")?"有效游玩次数":"O20 + N10":row.optString("subtitle"),12,AppUi.MUTED,false,2));card.addView(info,new LayoutParams(0,-2,1));LinearLayout number=AppUi.column(host,0);number.setGravity(Gravity.RIGHT);TextView val=text(value(id,row),16,AppUi.ACCENT,true,2);val.setGravity(Gravity.RIGHT);number.addView(val);if(playerId(id))number.addView(AppUi.text(host,id.startsWith("activity_")?"次":"rating",12,AppUi.MUTED,false));LayoutParams np=new LayoutParams(dp(playerId(id)?98:112),-2);np.leftMargin=dp(6);card.addView(number,np);action(card,id,row);return card;}
    private boolean extraId(String id){return id.equals("six_k")||id.startsWith("activity_");}
    private boolean playerId(String id){return id.equals("total")||extraId(id);}
    private String boardTitle(String id){return id.equals("six_k")?"6K 排行":id.equals("activity_month")?"近30天活跃榜":id.equals("activity_total")?"累计活跃榜":CommunityData.title(id);}
    private void loadExtras(){io.execute(()->{try{JSONObject activity=ExtraBoards.load(host,engine,"activity.json");JSONArray month=ExtraBoards.ranked(activity,"month"),total=ExtraBoards.ranked(activity,"total"),six=ExtraBoards.ranked(ExtraBoards.load(host,engine,"6k.json"),"rating");deliver(()->{extra.put("activity_month",month);extra.put("activity_total",total);extra.put("six_k",six);render();});}catch(Exception ignored){}});}
    private GradientDrawable surface(int color){GradientDrawable bg=AppUi.background(host,color);bg.setStroke(dp(1),AppUi.BORDER);return bg;}
    private TextView text(String value,int size,int color,boolean bold,int lines){TextView text=AppUi.text(host,value,size,color,bold);text.setMaxLines(lines);text.setEllipsize(android.text.TextUtils.TruncateAt.END);return text;}
    private String value(String id,JSONObject row){if(id.startsWith("activity_"))return String.format(Locale.ROOT,"%,d",row.optLong("plays"));if(id.equals("six_k"))return String.format(Locale.ROOT,"%.4f",row.optDouble("rating"));if(id.equals("total"))return String.format(Locale.ROOT,"%.4f",row.optDouble("rating"));if(CommunityData.good(id))return String.format(Locale.ROOT,"%.2f星 · %d评",row.optDouble("average"),row.optInt("rating_count"));return String.format(Locale.ROOT,"下载 %,d 次",row.optLong("downloads"));}
    private View art(String id,JSONObject row,int size){
        SongCatalogue.Song song=catalogue.forChart(row.optInt("cid"));if(id.startsWith("song_")&&song!=null){ImageView image=new ImageView(host);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(AppUi.background(host,AppUi.SOFT));image.setClipToOutline(true);image.setContentDescription(song.title+"曲绘");image.setLayoutParams(new LayoutParams(dp(size),dp(size)));SongArtwork.load(host,image,song);return image;}
        String name=row.optString("name","?");TextView initial=AppUi.text(host,name.isEmpty()?"?":name.substring(0,name.offsetByCodePoints(0,1)).toUpperCase(Locale.ROOT),22,AppUi.ACCENT,true);initial.setGravity(Gravity.CENTER);initial.setBackground(AppUi.background(host,AppUi.SELECTED));initial.setLayoutParams(new LayoutParams(dp(size),dp(size)));return initial;
    }
    private void action(View card,String id,JSONObject row){if(!id.startsWith("song_"))return;SongCatalogue.Song song=catalogue.forChart(row.optInt("cid"));if(song==null)return;card.setOnClickListener(v->SongPanel.details(host,song,(s,cid)->openSingle(cid)));card.setFocusable(true);}
    private View preview(String id,JSONObject row){
        LinearLayout card=AppUi.column(host,10);card.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x24076d78),surface(playerId(id)&&engine.profile.equals(row.optString("qq"))?AppUi.SELECTED:AppUi.CARD),null));card.setGravity(Gravity.CENTER_HORIZONTAL);
        TextView rank=text("#"+row.optInt("rank"),13,row.optInt("rank")<=3?AppUi.GOLD:AppUi.MUTED,true,1);card.addView(rank);AppUi.space(card,4);card.addView(art(id,row,40));AppUi.space(card,4);TextView name=text(row.optString("name"),14,AppUi.INK,true,2);name.setGravity(Gravity.CENTER);name.setMinLines(2);card.addView(name,new LayoutParams(-1,-2));TextView value=text(value(id,row),playerId(id)?20:14,AppUi.ACCENT,true,1);value.setGravity(Gravity.CENTER);card.addView(value,new LayoutParams(-1,-2));TextView subtitle=text(extraId(id)?(id.equals("six_k")?"6K · O20 + N10":"游玩次数"):id.equals("total")?"rating · O20 + N10":row.optString("subtitle"),12,AppUi.MUTED,false,1);subtitle.setGravity(Gravity.CENTER);card.addView(subtitle,new LayoutParams(-1,-2));action(card,id,row);return card;
    }
    private String explanation(String id){if(extraId(id))return id.equals("six_k")?"仅6K谱面 · O20+N10 · 缺位按0计":"已上传的有效游玩记录 · 去重后计次";if(id.equals("total"))return "O20 + N10 · 统一默认规则 · 前50名";if(id.equals("song_hot"))return "同一歌曲各谱面下载次数相加 · 前50名";if(id.equals("creator_hot"))return "按谱师署名汇总作品下载次数 · 前50名";return "按平均星级排序，同分优先评价数 · 前50名";}
    private void more(String id){
        clear();page=1;boardId=id;title(boardTitle(id));buttons("返回榜单首页",this::home,"刷新榜单",()->load(true));addView(AppUi.text(host,explanation(id),13,AppUi.MUTED,false));if(id.equals("creator_hot"))creatorToggle(this);labelStatus();JSONArray data=rows(id);ListView list=new ListView(host);list.setDivider(new ColorDrawable(AppUi.BG));list.setDividerHeight(dp(10));list.setSelector(new ColorDrawable(android.graphics.Color.TRANSPARENT));list.setPadding(0,0,0,dp(12));list.setClipToPadding(false);addView(list,new LayoutParams(-1,0,1));
        if(data.length()==0){list.setAdapter(new ArrayAdapter<>(host,android.R.layout.simple_list_item_1,new String[]{CommunityData.good(id)?"暂无评价，可从歌曲页发表评论并打分":"暂无已发布数据"}));return;}
        list.setAdapter(new BaseAdapter(){public int getCount(){return Math.min(50,data.length());}public Object getItem(int p){return data.optJSONObject(p);}public long getItemId(int p){return p;}public View getView(int p,View recycled,ViewGroup parent){JSONObject row=data.optJSONObject(p);LinearLayout card=AppUi.column(host,14);card.setBackground(surface(playerId(id)&&engine.profile.equals(row.optString("qq"))?AppUi.SELECTED:AppUi.CARD));LinearLayout top=new LinearLayout(host);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(text("#"+row.optInt("rank"),20,row.optInt("rank")<=3?AppUi.GOLD:AppUi.MUTED,true,1),new LayoutParams(dp(52),-2));top.addView(art(id,row,48));LinearLayout info=AppUi.column(host,0);LayoutParams ip=new LayoutParams(0,-2,1);ip.leftMargin=dp(12);top.addView(info,ip);info.addView(text(row.optString("name"),17,AppUi.INK,true,2));info.addView(text(value(id,row),18,AppUi.ACCENT,true,1));info.addView(text(id.equals("total")?String.format(Locale.ROOT,"O20 %.4f · N10 %.4f",row.optDouble("o"),row.optDouble("n")):row.optString("subtitle"),12,AppUi.MUTED,false,2));card.addView(top);action(card,id,row);return card;}});
    }
    private void openSingle(int cid){clear();page=2;setPadding(0,0,0,0);remember.accept(true,cid);singlePanel=new RankingPanel(host,engine,true,cid,query,(single,chosen)->remember.accept(true,chosen),value->{query=value;searchMemory.accept(value);},this::home);addView(singlePanel,new LayoutParams(-1,-1));}
    private void deliver(Runnable action){host.runOnUiThread(()->{if(!closed&&!host.isDestroyed())action.run();});}
    private void render(){if(page==0)home();else if(page==1)more(boardId);}
    private CommunityData.Boards fallback()throws Exception {RankingRepository.Snapshot source=RankingRepository.refresh(host,engine,false,progress->{});JSONObject data=new JSONObject();for(String id:CommunityData.IDS)data.put(id,new JSONArray());JSONArray totals=data.getJSONArray("total");for(RankingData.Player player:RankingData.total(source.players)){if(totals.length()==50)break;totals.put(RankingData.encode(player).put("rank",player.rank));}CommunityData.Boards result=new CommunityData.Boards();result.doc=new JSONObject().put("schema",1).put("server",engine.server).put("revision",RankingIndex.revision(engine.server,engine.charts())).put("updated",source.updated).put("boards",data);result.cached=true;return result;}
    private void load(boolean force){if(closed||loading)return;loadExtras();loading=true;notice="";int current=++request;if(status!=null)status.setText("正在读取榜单…");
        io.execute(()->{try{CommunityData.Boards cache=CommunityRepository.cachedBoards(host,engine);if(cache!=null)deliver(()->{if(current!=request)return;boards=cache;render();});CommunityData.Boards next=CommunityRepository.boards(host,engine,force);deliver(()->{if(current!=request)return;boards=next;catalogue=new SongCatalogue(engine.charts());loading=false;notice="";render();});}
            catch(Exception failure){CommunityData.Boards legacy=null;if(boards==null)try{legacy=fallback();}catch(Exception ignored){}final CommunityData.Boards saved=legacy;deliver(()->{if(current!=request)return;if(saved!=null)boards=saved;loading=false;notice="社区榜单刷新未完成，保留已有总榜与缓存。";render();});}});
    }
    public boolean back(){if(page==0)return false;if(page==2&&singlePanel!=null&&singlePanel.backToChooser())return true;home();return true;}
    public void close(){closed=true;request++;if(singlePanel!=null)singlePanel.close();io.shutdown();}
}
